'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=()=>crypto.randomUUID(), today=()=>new Date().toISOString(), fmt=n=>Number(n||0).toLocaleString('de-DE',{maximumFractionDigits:2});
const empty=()=>({version:1,products:[],units:[],movements:[],events:[],counts:[]});let state=empty(),page='Übersicht',scanner=null,backupReminderShown=false,cloudAccessToken=null,cloudUserId=null;
function db(){return new Promise((resolve,reject)=>{const r=indexedDB.open('schlesisches-tor-offline',1);r.onupgradeneeded=()=>r.result.createObjectStore('data');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function load(){const d=await db();return new Promise((resolve,reject)=>{const t=d.transaction('data','readonly');const r=t.objectStore('data').get('state');r.onsuccess=()=>resolve(r.result||empty());r.onerror=()=>reject(r.error);t.oncomplete=()=>d.close()})}
async function save(){state.lastLocalChangeAt=today();const d=await db();return new Promise((resolve,reject)=>{const t=d.transaction('data','readwrite');t.objectStore('data').put(state,'state');t.oncomplete=()=>{d.close();$('#saveStatus').textContent='· Gespeichert';resolve()};t.onerror=()=>reject(t.error)})}
function toast(msg){const el=$('#toast');el.textContent=msg;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',3200)}
function qty(p,loc){return state.units.filter(u=>u.product===p&&u.location===loc).reduce((n,u)=>n+u.ml,0)}
function unitLabel(p){return p.category==='Cocktail-Dekoration'?(p.name==='Minze'?'Bund':p.name==='Gefrorene Himbeeren'?'Packung':'Stück'):'ml'}
function amount(p,loc){if(p.category==='Cocktail-Dekoration')return fmt(qty(p.id,loc))+' '+unitLabel(p);const units=state.units.filter(u=>u.product===p&&u.location===loc);const whole=units.filter(u=>u.ml===p.size).length;const opened=units.filter(u=>u.ml<p.size).map(u=>u.ml);return `${whole} ganz${opened.length?` · ${opened.length} offen (${opened.map(v=>fmt(v)).join(' + ')} ml)`:''} · ${fmt(qty(p.id,loc)/1000)} l`}
function product(pid){return state.products.find(p=>p.id===pid)}
function active(){return state.events.find(e=>!e.end)}
function optProducts(){return state.products.map(p=>`<option value="${p.id}">${esc(p.name)} (${p.category==='Cocktail-Dekoration'?esc(unitLabel(p)):fmt(p.size)+' ml'})</option>`).join('')}
function record(type,pid,from,to,ml,detail=''){state.movements.push({id:id(),at:today(),type,product:pid,from,to,ml,detail,event:active()?.id||null})}
function take(pid,loc,ml){let left=ml;const units=state.units.filter(u=>u.product===pid&&u.location===loc).sort((a,b)=>(a.mhd||'9999-12-31').localeCompare(b.mhd||'9999-12-31')||a.ml-b.ml);if(units.reduce((n,u)=>n+u.ml,0)<ml)throw Error('Nicht genug Bestand');for(const u of units){if(!left)break;const n=Math.min(left,u.ml);u.ml-=n;left-=n}state.units=state.units.filter(u=>u.ml>0)}
function add(pid,loc,ml,mhd='',lot=''){const p=product(pid);while(ml>0){const part=Math.min(p.size,ml);state.units.push({id:id(),product:pid,location:loc,ml:part,...(mhd?{mhd}:{}),...(lot?{lot}:{})});ml-=part}}
function moveStock(pid,from,to,ml){const selected=state.units.filter(u=>u.product===pid&&u.location===from).sort((a,b)=>(a.mhd||'9999-12-31').localeCompare(b.mhd||'9999-12-31'));if(selected.reduce((n,u)=>n+u.ml,0)<ml)throw Error('Nicht genug Bestand');let left=ml;for(const u of selected){if(!left)break;const part=Math.min(u.ml,left);u.ml-=part;state.units.push({id:id(),product:pid,location:to,ml:part,...(u.mhd?{mhd:u.mhd}:{}),...(u.lot?{lot:u.lot}:{})});left-=part}state.units=state.units.filter(u=>u.ml>0)}
function eventRows(e){const ids=new Set([...(e.startStock||[]).map(x=>x.product),...(e.endStock||[]).map(x=>x.product),...state.movements.filter(m=>m.event===e.id).map(m=>m.product)]);return [...ids].map(pid=>{const p=product(pid)||state.deletedProducts?.[pid],a=(e.startStock||[]).find(x=>x.product===pid)||{},z=(e.endStock||[]).find(x=>x.product===pid)||{},moves=state.movements.filter(m=>m.event===e.id&&m.product===pid),dual=!!e.dualCount;const start=(a.bar||0)+(dual?(a.lager||0):0),end=(z.bar||0)+(dual?(z.lager||0):0),incoming=moves.filter(m=>m.type==='in'&&(dual?['bar','lager'].includes(m.to):m.to==='bar')).reduce((n,m)=>n+m.ml,0)+(dual?0:moves.filter(m=>m.type==='move'&&m.to==='bar').reduce((n,m)=>n+m.ml,0)),outgoing=dual?moves.filter(m=>['loss','use','break'].includes(m.type)).reduce((n,m)=>n+m.ml,0):moves.filter(m=>m.type==='move'&&m.from==='bar').reduce((n,m)=>n+m.ml,0);return {name:p?.name||'Unbekannt',size:p?.size||0,start,incoming,outgoing,end,used:start+incoming-outgoing-end}})}
function exportEvent(e){const lines=['Artikel;Gebinde ml;Anfang gesamt ml;Zugang ml;Sonstige Entnahme ml;Ende gesamt ml;Verbrauch ml'];for(const r of eventRows(e))lines.push(['"'+r.name.replaceAll('"','""')+'"',r.size,r.start,r.incoming,r.outgoing,r.end,r.used].join(';'));download('Veranstaltung-'+e.start.slice(0,10)+'.csv','\ufeff'+lines.join('\r\n'),'text/csv;charset=utf-8')}
function barchefDashboard(){const expired=state.units.filter(u=>u.mhd&&mhdDays(u.mhd)<0).length,soon=state.units.filter(u=>u.mhd&&mhdDays(u.mhd)>=0&&mhdDays(u.mhd)<=30).length,low=state.products.filter(p=>qty(p.id,'lager')+qty(p.id,'bar')<(p.min||0)).length,loss=state.movements.filter(m=>['loss','break'].includes(m.type)).length;return '<section class="card"><h2>Barchef-Tagesübersicht</h2><div class="grid"><div class="metric"><small>MHD überschritten</small><strong>'+expired+'</strong></div><div class="metric"><small>MHD in 30 Tagen</small><strong>'+soon+'</strong></div><div class="metric"><small>Unter Mindestbestand</small><strong>'+low+'</strong></div><div class="metric"><small>Verlustbuchungen</small><strong>'+loss+'</strong></div></div><div class="actions"><button data-nav="MHD-Kontrolle">MHD prüfen</button><button data-nav="Bar-Auffüllliste">Bar auffüllen</button><button data-nav="Erweiterte Auswertung">Auswertungen</button></div></section>'}
function changePage(p){stopScanner();page=p;render()}
const nav=['Übersicht','Artikel','Schnellbuchung','Sammelbuchung','Buchen','Veranstaltungen','Inventur','Gesamtinventur','Statistik','Bedarf','Erweiterte Auswertung','Bar-Auffüllliste','Verbrauchsprognose','MHD-Kontrolle','Synchronisierung','Sicherung'];
function render(){const tabs=[['Übersicht','⌂','Start'],['Artikel','▣','Bestände'],['Sammelbuchung','▥','Scanner'],['Erweiterte Auswertung','▤','Auswertung'],['Sicherung','☰','Mehr']];const current=page==='Übersicht'?'Übersicht':['Artikel','MHD-Kontrolle','Inventur','Gesamtinventur'].includes(page)?'Artikel':['Schnellbuchung','Sammelbuchung','Buchen'].includes(page)?'Sammelbuchung':['Statistik','Erweiterte Auswertung','Verbrauchsprognose','Bar-Auffüllliste'].includes(page)?'Erweiterte Auswertung':'Sicherung';$('#nav').innerHTML=tabs.map(([name,icon,label])=>'<button class="nav-tab '+(name===current?'active':'')+'" data-nav="'+name+'"><span class="nav-icon">'+icon+'</span><span>'+label+'</span></button>').join('');let html='';
if(page==='Übersicht'){const cats=[...new Set(state.products.map(p=>p.category))].sort();html=`<section class="home-tiles"><button class="home-tile tile-blue" data-nav="Übersicht"><span class="tile-icon">⌂</span><b>Übersicht</b><small>Tagesstatus</small></button><button class="home-tile " data-nav="Sammelbuchung"><span class="tile-icon">▥</span><b>Scanner</b><small>Buchen & Inventur</small></button><button class="home-tile " data-nav="Artikel"><span class="tile-icon">▣</span><b>Bestände</b><small>Hauptlager & Bar</small></button><button class="home-tile " data-nav="MHD-Kontrolle"><span class="tile-icon">▦</span><b>MHD & Chargen</b><small>Haltbarkeit & Lieferungen</small></button><button class="home-tile " data-nav="Veranstaltungen"><span class="tile-icon">▤</span><b>Veranstaltungen</b><small>Planen & Auswerten</small></button><button class="home-tile " data-nav="Bar-Auffüllliste"><span class="tile-icon">↔</span><b>Auffüllliste</b><small>Bar auffüllen</small></button><button class="home-tile " data-nav="Bedarf"><span class="tile-icon">▤</span><b>Einkaufsliste</b><small>Bedarf & Bestellen</small></button><button class="home-tile " data-nav="Erweiterte Auswertung"><span class="tile-icon">▥</span><b>Auswertungen</b><small>Verbrauch & Verluste</small></button></section>${barchefDashboard()}${state.events.some(e=>e.end&&(!state.lastBackupAt||e.end>state.lastBackupAt))?`<section class="card warn"><b>Datensicherung empfohlen</b><p>Seit dem letzten Backup wurde eine Veranstaltung abgeschlossen. Bitte unter Sicherung eine aktuelle JSON-Datei exportieren.</p></section>`:""}<section class="card"><h2>Bestandsübersicht</h2><div class="grid"><div class="metric"><small>Artikel</small><strong>${state.products.length}</strong></div><div class="metric"><small>Ganze Gebinde</small><strong>${state.units.filter(u=>u.ml===product(u.product)?.size).length}</strong></div><div class="metric"><small>Angebrochene Gebinde</small><strong>${state.units.filter(u=>u.ml<product(u.product)?.size).length}</strong></div><div class="metric"><small>Unter Mindestbestand</small><strong>${state.products.filter(p=>qty(p.id,'lager')+qty(p.id,'bar')<p.min).length}</strong></div></div></section><section class="card"><h2>Bestände durchsuchen</h2><label>Suche nach Name oder EAN</label><input id="stockSearch" placeholder="Getränk oder Barcode"><label>Kategorie</label><select id="stockCategory"><option value="">Alle Kategorien</option>${cats.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('')}</select><label>Lagerort</label><select id="stockLocation"><option value="all">Beide Lagerorte</option><option value="lager">Hauptlager</option><option value="bar">Bar</option></select><label>Bestand</label><select id="stockFilter"><option value="all">Alle Artikel</option><option value="low">Unter Mindestbestand</option><option value="available">Mit Bestand</option><option value="empty">Ohne Bestand</option></select><div id="stockResults"></div></section><section class="card"><h2>Veranstaltung</h2>${active()?`<p>Aktiv: <b>${esc(active().name)}</b></p>`:'<p>Keine laufende Veranstaltung</p>'}<button data-nav="Veranstaltungen">Veranstaltungen öffnen</button></section>`;}
if(page==='Artikel')html=`<section class="card"><h2>Neuen Artikel anlegen</h2><form id="newProduct"><label>Name</label><input name="name" required maxlength="100" placeholder="z. B. Wodka"><label>Kategorie</label><select name="category"><option>Spirituosen</option><option>Bier</option><option>Softdrinks</option><option>Säfte</option><option>Sirup</option><option>Wein / Sekt</option><option>Sonstiges</option><option>Cocktail-Dekoration</option></select><label>Gebindegröße (ml)</label><input name="size" type="number" min="1" max="100000" value="700" required><label>Barcode / EAN (optional)</label><input name="barcode" id="barcodeField" inputmode="numeric" maxlength="64"><div class="actions"><button type="button" class="secondary" id="scan">Kamera scannen</button></div><label>Vorhandene ganze Gebinde</label><input name="initial" type="number" min="0" value="0" required><label>Lagerort</label><select name="initialLocation"><option value="lager">Hauptlager</option><option value="bar">Bar</option></select><p id="lookupStatus" aria-live="polite"></p><button type="button" class="secondary" id="lookup">EAN online suchen</button><label>Mindestbestand gesamt (ganze Flaschen)</label><input name="min" type="number" min="0" max="100000" value="3" required><div id="camera"></div><div class="actions"><button>Artikel speichern</button></div></form></section><section class="card"><h2>Cocktail-Dekoration</h2><p>Ananas, Minze, Limette und Zitrone sowie gefrorene Himbeeren als Stück, Bund bzw. Packung verwalten. Die Artikel werden ohne Barcode angelegt und können über die Artikelauswahl gebucht und gezählt werden.</p><button type="button" class="secondary" id="addDecorations">Fehlende Dekorationen anlegen</button><h3>Gefrorene Himbeeren – Packungsinhalt per Barcode</h3><label>Barcode / EAN</label><input id="raspberryBarcode" inputmode="numeric" value="${esc(raspberryProduct()?.barcode||'')}" placeholder="Packung scannen"><button type="button" class="secondary" id="raspberryScan">Kamera scannen</button><button type="button" class="secondary" id="raspberryLookup">Inhalt online ermitteln</button><p id="raspberryStatus"></p><label>Gramm je Packung</label><input id="raspberryGrams" type="number" min="1" max="100000" value="${raspberryProduct()?.packGrams||''}" placeholder="z. B. 500"><button type="button" id="raspberrySave">Packungsdaten speichern</button></section><section class="card"><h2>Artikelübersicht</h2>${state.products.map(p=>`<div class="entry"><b>${esc(p.name)}</b><small>${esc(p.category)} · ${p.category==='Cocktail-Dekoration'?esc(unitLabel(p)):fmt(p.size)+' ml'} · ${esc(p.barcode||'ohne Barcode')}</small><small>Hauptlager: ${amount(p,'lager')}</small><small>Bar: ${amount(p,'bar')}</small><button type="button" class="secondary" data-edit-product="${p.id}">Artikel bearbeiten</button></div>`).join('')||'<p>Noch keine Artikel angelegt.</p>'}</section><section class="card"><h2>Artikelhistorie</h2><label>Artikel auswählen</label><select id="historyProduct">${optProducts()}</select><div id="historyResults"></div></section>`;
if(page==='Schnellbuchung')html=`<section class="card"><h2>Waren per Barcode buchen</h2><p>Bereits angelegte Artikel scannen, Anzahl eingeben und Wareneingang oder Umlagerung buchen.</p><form id="quickBooking"><label>Barcode / EAN</label><input id="quickBarcode" inputmode="numeric" placeholder="EAN eingeben oder scannen"><div class="actions"><button type="button" class="secondary" id="quickScan">Kamera scannen</button><button type="button" class="secondary" id="quickFind">Artikel suchen</button></div><div id="camera"></div><p id="quickStatus" aria-live="polite"></p><p id="quickFefo" class="warn" aria-live="polite"></p><label>Artikel</label><select name="pid" id="quickProduct">${optProducts()}</select><label>Aktion</label><select name="type" id="quickType"><option value="in">Wareneingang</option><option value="move">Hauptlager → Bar</option></select><label>Anzahl ganzer Gebinde</label><input name="quantity" type="number" min="1" max="100000" step="1" value="1" required><label>Wareneingang einlagern in</label><select name="location"><option value="lager">Hauptlager</option><option value="bar">Bar</option></select><div id="quickMhdWrap"><label>MHD der Lieferung (optional)</label><input name="mhd" type="date"><small>Wird bei Wareneingang für alle gebuchten Flaschen gespeichert.</small></div><label>Bemerkung (optional)</label><input name="detail" maxlength="150"><button>Buchung speichern</button></form></section>`;
if(page==='Sammelbuchung')html=`<section class="card"><h2>Mehrere Getränke auf einmal buchen</h2><p>Artikel und Mengen zusammenstellen und alle Buchungen in einem Schritt speichern.</p><label>Buchungsart</label><select id="batchType"><option value="in">Wareneingang</option><option value="move">Hauptlager → Bar</option><option value="use">Sonstige Entnahme</option><option value="loss">Bruch / Verlust</option></select><label>Standort für Wareneingang oder Entnahme</label><select id="batchLocation"><option value="lager">Hauptlager</option><option value="bar">Bar</option></select><label>Barcode / EAN</label><input id="batchBarcode" inputmode="numeric" placeholder="EAN scannen oder eingeben"><div class="actions"><button type="button" class="secondary" id="batchScan">Kamera scannen</button><button type="button" class="secondary" id="batchFind">Artikel suchen</button></div><div id="camera"></div><p id="batchStatus" aria-live="polite"></p><p id="batchFefo" class="warn" aria-live="polite"></p><p>Im Dauerscan-Modus wird jeder erkannte Artikel automatisch einmal zur Liste hinzugefügt. Gleiche Artikel werden zusammengezählt.</p><label><input type="checkbox" id="batchContinuous"> Dauerscanner (je Scan 1 Gebinde)</label><label>Artikel</label><select id="batchProduct">${optProducts()}</select><label>Anzahl ganzer Flaschen / Gebinde</label><input id="batchQty" type="number" min="1" max="100000" step="1" value="1"><button type="button" id="batchAdd">Artikel zur Liste hinzufügen</button><div id="batchItems"></div><div id="batchMhdWrap"><label>MHD der Lieferung (optional)</label><input id="batchMhd" type="date"><small>Gilt für alle Artikel dieser Lieferung. Für unterschiedliche MHD getrennt buchen.</small></div><label>Bemerkung (optional)</label><input id="batchDetail" maxlength="150"><button type="button" id="batchSave">Alle Buchungen speichern</button></section>`;
if(page==='Buchen')html=`<section class="card"><h2>Warenbewegung buchen</h2>${state.products.length?`<form id="booking"><label>Buchungsart</label><select name="type" id="type"><option value="in">Wareneingang</option><option value="move">Umlagerung</option><option value="use">Sonstige Entnahme</option><option value="loss">Bruch / Verlust</option></select><label>Artikel</label><select name="pid">${optProducts()}</select><label>Standort</label><select name="location"><option value="lager">Hauptlager</option><option value="bar">Bar</option></select><label>Menge</label><input type="number" name="quantity" min="1" step="1" required value="1"><label>Einheit</label><select name="unit"><option value="bottle">Ganze Flaschen</option><option value="ml">Milliliter (auch angebrochen)</option></select><label>Bemerkung (optional)</label><input name="detail" maxlength="150"><p>Bei Umlagerung wird die Menge vom gewählten Standort an den anderen übertragen. Bei Verbrauch wird die Menge aus dem gewählten Standort abgezogen.</p><button>Buchung speichern</button></form>`:'<p>Lege zuerst einen Artikel an.</p>'}</section><section class="card"><h2>Letzte Buchungen</h2><p>Fehlerhafte Buchungen können durch eine dokumentierte Gegenbuchung korrigiert werden.</p>${state.movements.slice(-15).reverse().map(m=>`<div class="entry"><b>${esc(product(m.product)?.name||'Gelöschter Artikel')} · ${fmt(m.ml)} ml</b><small>${esc(m.type)} · ${new Date(m.at).toLocaleString('de-DE')} · ${esc(m.from||'–')} → ${esc(m.to||'–')}</small>${['in','move','use','loss'].includes(m.type)&&!state.movements.some(x=>x.reversalOf===m.id)?`<button type="button" class="secondary" data-reverse="${m.id}">Buchung korrigieren</button>`:''}</div>`).join('')||'<p>Keine Buchungen.</p>'}</section>`;
if(page==='Veranstaltungen'){const event=active(),draft=state.eventCountDraft,stage=event?'end':'start';html=`<section class="card"><h2>Veranstaltungszählung</h2><p>${event?'Endzählung: '+esc(event.name):'Vorbereitung: Bar und Hauptlager vor Veranstaltungsbeginn zählen'}</p><p>Scanne eine volle Flasche und tippe „Voll“. Für angebrochene Flaschen wähle den Füllstand in 5-%-Schritten. Beide Lagerorte werden getrennt erfasst.</p><label>Lagerort</label><select id="eventCountLocation"><option value="bar">Bar</option><option value="lager">Hauptlager</option></select><label>Barcode / EAN</label><input id="eventCountBarcode" inputmode="numeric" placeholder="Barcode scannen"><button type="button" id="eventCountScan" class="secondary">Kamera starten</button><button type="button" id="eventCountFind" class="secondary">Barcode übernehmen</button><label>Artikel ohne Barcode auswählen</label><select id="eventCountProduct"><option value="">Artikel wählen</option>${state.products.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select><button type="button" class="secondary" id="eventCountChoose">Artikel übernehmen</button><div id="camera"></div><p id="eventCountStatus"></p><div id="eventCountActions"></div><h3>Gezählte Getränke</h3><div id="eventCountList"></div><div id="eventCountProgress"></div><button type="button" id="eventCountClear" class="secondary">Aktuelle Zählung zurücksetzen</button>${event?'<button type="button" id="eventCountFinish">Beide Endbestände bestätigen und Veranstaltung abschließen</button>':'<label>Veranstaltungsname</label><input id="eventCountName" maxlength="100" placeholder="Name der Veranstaltung"><button type="button" id="eventCountStart">Beide Anfangsbestände übernehmen und Veranstaltung starten</button>'}</section><section class="card"><h2>Veranstaltungsberichte</h2>${state.events.slice().reverse().map(v=>`<div class="entry"><b>${esc(v.name)}</b><small>${v.end?'Abgeschlossen':'Aktiv'}</small>${v.end?`<button type="button" class="secondary" data-report="${v.id}">Verbrauchsbericht CSV</button><button type="button" class="secondary" data-pdf="${v.id}">Bericht als PDF</button>`:''}</div>`).join('')}</section>`;}
if(page==='Inventur')html=`<section class="card"><h2>Inventur</h2><p>Erfasse den tatsächlichen Bestand in ganzen Flaschen und den Restinhalt aller angebrochenen Flaschen in ml. Die Korrektur wird mit Differenz dokumentiert.</p>${state.products.length?`<form id="count"><label>Barcode scannen oder eingeben</label><div class="actions"><input id="inventoryBarcode" inputmode="numeric" placeholder="EAN / GTIN"><button type="button" class="secondary" id="scanInventory">Kamera scannen</button><button type="button" class="secondary" id="findInventory">Suchen</button></div><div id="camera"></div><label><input type="checkbox" id="inventoryContinuous"> Inventur-Dauerscanner (1 Gebinde je bestätigtem Scan)</label><p id="inventoryScanStatus" aria-live="polite"></p><div id="inventoryScanItems"></div><button type="button" id="inventoryApplyScans">Gezählte Gebinde zur Inventur übernehmen</button><p id="inventoryStatus" aria-live="polite"></p><label>Artikel</label><select name="pid" id="inventoryProduct">${optProducts()}</select><label>Standort</label><select name="location"><option value="lager">Hauptlager</option><option value="bar">Bar</option></select><label>Ganze Flaschen</label><input name="whole" type="number" min="0" max="100000" value="0" required><label>Angebrochene Flaschen: Restmengen in ml, durch Komma getrennt</label><input name="opened" placeholder="z. B. 250, 400"><label>Bemerkung</label><input name="detail" maxlength="150"><button>Inventur übernehmen</button></form>`:'<p>Lege zuerst Artikel an.</p>'}</section><section class="card"><h2>Letzte Zählungen</h2>${state.counts.slice(-10).reverse().map(c=>`<div class="entry"><b>${esc(product(c.product)?.name||'?')}</b><small>${esc(c.location)} · ${fmt(c.before)} → ${fmt(c.after)} ml · Differenz ${fmt(c.after-c.before)} ml</small></div>`).join('')||'<p>Keine Inventur vorhanden.</p>'}</section>`;
if(page==='Gesamtinventur')html=`<section class="card"><h2>Gesamtinventur</h2><p>Wähle den Lagerort und zähle die Artikel. Nur markierte Artikel werden beim Abschluss geändert; nicht gezählte Artikel bleiben unverändert.</p><label>Lagerort</label><select id="bulkLocation"><option value="lager">Hauptlager</option><option value="bar">Bar</option></select><div id="bulkRows"></div><button id="bulkApply">Markierte Zählungen übernehmen</button></section>`;
if(page==='Statistik')html=`<section class="card"><h2>Verbrauchsstatistik</h2><p>Aus abgeschlossenen Veranstaltungen, auf Basis der dokumentierten Barbestände.</p><label>Veranstaltung</label><select id="statEvent"><option value="all">Alle abgeschlossenen Veranstaltungen</option>${state.events.filter(e=>e.end).map(e=>`<option value="${e.id}">${esc(e.name)} · ${new Date(e.start).toLocaleDateString('de-DE')}</option>`).join('')}</select><div id="statRows"></div></section>`;
if(page==='Bedarf')html=`<section class="card"><h2>Automatische Nachbestellliste</h2><p>Mindestbestand bezieht sich auf Hauptlager und Bar zusammen. Die vorgeschlagene Menge füllt bis zum Mindestbestand auf.</p><div id="needRows">${state.products.filter(p=>qty(p.id,'lager')+qty(p.id,'bar')<p.min).map(p=>{const have=qty(p.id,'lager')+qty(p.id,'bar'),missing=Math.ceil((p.min-have)/p.size);return `<div class="entry"><b>${esc(p.name)}</b><small>Vorhanden: ${fmt(have/1000)} l · Mindestbestand: ${fmt(p.min/1000)} l</small><small>Nachbestellen: ${fmt(missing)} ganze Gebinde à ${fmt(p.size)} ml</small></div>`}).join('')||'<p>Aktuell keine Fehlmengen.</p>'}</div><button id="exportNeed" class="secondary">Nachbestellliste als CSV</button></section>`;
if(page==='Erweiterte Auswertung')html=renderExtendedReports();
if(page==='Synchronisierung')html=renderSyncStatus();
if(page==='MHD-Kontrolle')html=renderMhdControl();
if(page==='Bar-Auffüllliste')html=renderBarRefill();
if(page==='Verbrauchsprognose')html=renderForecast();
if(page==='Sicherung')html=`<section class="card"><h2>Datensicherung</h2><p>Deine Daten befinden sich ausschließlich auf diesem Gerät. Erstelle nach jeder Veranstaltung eine Sicherungsdatei und bewahre sie außerhalb des Browsers auf, zum Beispiel in der Dateien-App.</p><button id="backup">Sicherung als JSON exportieren</button><p id="backupInfo"></p><button type="button" class="secondary" id="validateBackup">Sicherungsdatei prüfen (ohne Import)</button><h3>Sicherung wiederherstellen</h3><p class="warn">Beim Wiederherstellen werden sämtliche aktuellen App-Daten durch den Inhalt der Datei ersetzt. Vorher eine Sicherung exportieren!</p><input type="file" id="restoreFile" accept="application/json,.json"><button id="restore" class="secondary">Datei prüfen und wiederherstellen</button></section><section class="card"><h2>Installation auf iPhone</h2><p>Einmal über HTTPS in Safari öffnen, dann Teilen → Zum Home-Bildschirm. Danach ist die App bei erfolgreichem Offline-Caching ohne Netz nutzbar.</p><p>Wichtig: Safari-Daten oder die App nicht löschen, bevor eine Sicherung erstellt wurde. Kein automatischer Abgleich mit dem iPad.</p></section>`;
if(page==='Sicherung')html='<section class="card"><h2>Weitere Bereiche</h2><div class="more-grid">'+nav.filter(n=>!['Übersicht','Artikel','Sammelbuchung','Sicherung'].includes(n)).map(n=>'<button class="more-link" data-nav="'+esc(n)+'">'+esc(n)+' <span>›</span></button>').join('')+'</div></section>'+html;$('#app').innerHTML=html;bind()}
async function mutate(fn){try{fn();await save();render();toast('Gespeichert')}catch(e){toast('Fehler: '+e.message)}}
