function renderForecast(){return '<section class="card"><h2>Verbrauchsprognose</h2><p>Unverbindlicher Durchschnitt aus abgeschlossenen Veranstaltungen; keine automatische Bestandsänderung. Mengen je Artikel in ml oder Stück entsprechend der Artikelart.</p><label>Vergangene Veranstaltungen</label><select id="forecastEvents"><option value="3">Letzte 3</option><option value="5">Letzte 5</option><option value="10">Letzte 10</option><option value="all">Alle</option></select><div id="forecastRows"></div></section>'}
function forecastData(limit=3){const events=state.events.filter(e=>e.end).sort((a,b)=>b.start.localeCompare(a.start));const selected=limit==='all'?events:events.slice(0,Number(limit));const totals=new Map();for(const e of selected)for(const row of eventRows(e)){const key=row.name+'|'+row.size;totals.set(key,(totals.get(key)||0)+row.used)}return {count:selected.length,items:[...totals].map(([key,total])=>({name:key.split('|')[0],size:Number(key.split('|')[1]),average:total/selected.length})).sort((a,b)=>b.average-a.average)}}
function renderForecastRows(){const out=$('#forecastRows');if(!out)return;const data=forecastData($('#forecastEvents')?.value||'3');out.innerHTML='<p>Basis: '+data.count+' abgeschlossene Veranstaltung(en)</p>'+(data.count?data.items.map(x=>'<div class="entry"><b>'+esc(x.name)+'</b><small>Durchschnitt '+fmt(x.average)+' Einheiten · ca. '+fmt(x.size>0?Math.ceil(Math.max(0,x.average)/x.size):0)+' ganze Gebinde pro Veranstaltung</small></div>').join(''):'<p>Noch keine abgeschlossenen Veranstaltungen.</p>')}
function refillSuggestions(){return state.products.map(p=>{const target=Math.max(0,Math.ceil((p.barTarget??p.min??0)/p.size)),atBar=Math.floor(qty(p.id,'bar')/p.size),available=Math.floor(qty(p.id,'lager')/p.size),suggest=Math.min(Math.max(0,target-atBar),available);return {p,target,atBar,available,suggest}}).filter(x=>x.suggest>0)}
function renderBarRefill(){const rows=refillSuggestions();return '<section class="card"><h2>Automatische Bar-Auffüllliste</h2><p>Vorschlag: Bar bis zum eingestellten Bar-Sollbestand auffüllen. Falls kein eigener Bar-Sollbestand erfasst ist, wird der bisherige Mindestbestand als Vorschlag verwendet. Nur volle Gebinde im Hauptlager werden berücksichtigt. Vor dem Buchen die tatsächlich umgelagerten Mengen prüfen.</p>'+(rows.map(x=>'<div class="entry"><b>'+esc(x.p.name)+'</b><small>Bar: '+x.atBar+' · Hauptlager: '+x.available+' · Soll: '+x.target+'</small><label>Umlagern (ganze Gebinde)</label><input type="number" min="0" max="'+x.available+'" step="1" value="'+x.suggest+'" data-refill="'+esc(x.p.id)+'"></div>').join('')||'<p>Kein Auffüllbedarf oder kein Hauptlagerbestand.</p>')+'<button type="button" id="refillApply">Ausgewählte Umlagerungen buchen</button></section>'}
