let inventoryScans=new Map();
function captureInventoryScan(barcode){const p=state.products.find(x=>x.barcode===barcode),status=$('#inventoryScanStatus');if(!p){if(status)status.textContent='EAN nicht gefunden: '+barcode;return}inventoryScans.set(p.id,(inventoryScans.get(p.id)||0)+1);if(status)status.textContent='Gezählt: '+p.name+' · '+inventoryScans.get(p.id)+' Gebinde. Für erneuten Scan desselben Artikels mindestens 2,5 Sekunden warten.';renderInventoryScans()}
function renderInventoryScans(){const out=$('#inventoryScanItems');if(!out)return;out.innerHTML=[...inventoryScans].map(([pid,q])=>'<div class="entry"><b>'+esc(product(pid)?.name||'Unbekannt')+'</b><small>'+q+' gescannte Gebinde</small><button type="button" class="secondary" data-scan-remove="'+esc(pid)+'">Entfernen</button></div>').join('');out.querySelectorAll('[data-scan-remove]').forEach(b=>b.onclick=()=>{inventoryScans.delete(b.dataset.scanRemove);renderInventoryScans()})}
async function applyInventoryScans(){const loc=$('#count select[name="location"]')?.value;if(!['lager','bar'].includes(loc)||!inventoryScans.size)return toast('Keine Inventur-Scans');if(!confirm('Gezählte ganze Gebinde am Standort '+loc+' übernehmen? Nicht gescannte Artikel bleiben unverändert. Angebrochene Gebinde der gescannten Artikel bleiben erhalten.'))return;for(const [pid,n] of inventoryScans){const p=product(pid);if(!p)continue;const old=state.units.filter(u=>u.product===pid&&u.location===loc),whole=old.filter(u=>u.ml===p.size).sort((a,b)=>(a.mhd||'9999-12-31').localeCompare(b.mhd||'9999-12-31')),opened=old.filter(u=>u.ml<p.size),before=qty(pid,loc);state.units=state.units.filter(u=>!(u.product===pid&&u.location===loc));state.units.push(...opened,...whole.slice(0,n));for(let i=whole.length;i<n;i++)state.units.push({id:id(),product:pid,location:loc,ml:p.size});const after=qty(pid,loc);state.counts.push({id:id(),at:today(),product:pid,location:loc,before,after,detail:'Dauerscanner-Inventur; MHD neuer Gebinde unbekannt'});record('inventur',pid,loc,loc,after-before,'Dauerscanner-Inventur')}inventoryScans.clear();await save();render();toast('Inventur übernommen')}
function lossSummary(){const entries=state.movements.filter(m=>['loss','break'].includes(m.type));const byProduct=new Map();for(const m of entries){const old=byProduct.get(m.product)||{count:0,ml:0};old.count++;old.ml+=m.ml;byProduct.set(m.product,old)}return [...byProduct].map(([pid,v])=>({p:product(pid),...v})).filter(x=>x.p).sort((a,b)=>b.ml-a.ml)}
