async function saveWasteEntry(e){e.preventDefault();const f=new FormData(e.target),pid=String(f.get('pid')),loc=String(f.get('location')),q=Number(f.get('quantity')),p=product(pid);if(!p||!['bar','lager'].includes(loc)||!Number.isSafeInteger(q)||q<1||q>100000)return toast('Ungültige Eingabe');const ml=q*p.size;if(qty(pid,loc)<ml)return toast('Nicht genug Bestand für die Entsorgung');const reason=String(f.get('reason')),detail=String(f.get('detail')||'');try{take(pid,loc,ml);record('loss',pid,loc,'',ml,reason+(detail?' – '+detail:''));await save();render();toast('Entsorgung dokumentiert')}catch(err){toast('Fehler: '+err.message)}}

/* MHD pro Gebinde: alte Bestände ohne MHD bleiben ausdrücklich 'nicht erfasst'. */
function mhdDays(date){const a=new Date(date+'T12:00:00Z'),b=new Date(new Date().toISOString().slice(0,10)+'T12:00:00Z');return Math.round((a-b)/86400000)}
function fefoHint(pid,loc){const p=product(pid);if(!p)return '';const lots=state.units.filter(u=>u.product===pid&&u.location===loc&&u.ml>0).sort((a,b)=>(a.mhd||'9999-12-31').localeCompare(b.mhd||'9999-12-31'));if(!lots.length)return 'Kein Bestand am gewählten Lagerort.';const first=lots.find(u=>u.mhd);if(!first)return 'MHD nicht erfasst – bitte Bestand prüfen.';const days=mhdDays(first.mhd),same=lots.filter(u=>u.mhd===first.mhd).reduce((n,u)=>n+u.ml,0);return 'Zuerst entnehmen: MHD '+first.mhd+' ('+fmt(same/p.size)+' Gebindeäquivalent(e))'+(days<0?' · MHD überschritten – Ware vor Verwendung prüfen!':days===0?' · MHD heute erreicht':' · noch '+days+' Tage')+(lots.some(u=>!u.mhd)?' · weiterer Bestand ohne MHD vorhanden':'')}
function updateFefoHints(){const quick=$('#quickFefo');if(quick)quick.textContent=fefoHint($('#quickProduct')?.value,$('#quickType')?.value==='move'?'lager':$('#quickBooking select[name="location"]')?.value||'lager');const batch=$('#batchFefo');if(batch)batch.textContent=fefoHint($('#batchProduct')?.value,$('#batchType')?.value==='move'?'lager':$('#batchLocation')?.value||'lager')}
function renderMultiMhd(){return '<section class="card"><h2>Lieferung mit mehreren MHD / Chargen</h2><p>Mehrere Chargen eines Artikels mit jeweils eigenem MHD und optionaler Chargennummer in einer Lieferung erfassen. Je Zeile eine Charge; durch Semikolon trennen: MHD;Anzahl;Charge (optional).</p><form id="multiMhdForm"><label>Artikel</label><select name="pid">'+optProducts()+'</select><label>Lagerort</label><select name="location"><option value="lager">Hauptlager</option><option value="bar">Bar</option></select><label>Chargen (eine pro Zeile)</label><textarea name="lots" rows="5" required placeholder="2027-02-15;12;L123&#10;2027-03-20;24;L124"></textarea><button>Gesamte Lieferung speichern</button></form></section>'}
async function receiveMultiMhd(e){e.preventDefault();try{const f=new FormData(e.target),pid=String(f.get('pid')),loc=String(f.get('location')),p=product(pid);if(!p||!['lager','bar'].includes(loc))throw Error('Artikel oder Lagerort ungültig');const lines=String(f.get('lots')).trim().split(/\r?\n/).filter(Boolean),items=lines.map(line=>{const [mhd,raw,lot='',...rest]=line.split(';').map(x=>x.trim()),q=Number(raw);if(rest.length||!/^(?:19|20|21)\d{2}-\d{2}-\d{2}$/.test(mhd)||!Number.isSafeInteger(q)||q<1||q>100000||lot.length>80||new Date(mhd+'T12:00:00Z').toISOString().slice(0,10)!==mhd)throw Error('Ungültige Chargenzeile: '+line);return {mhd,q,lot}});if(!items.length||items.length>100||!Number.isSafeInteger(items.reduce((n,x)=>n+x.q*p.size,0)))throw Error('Ungültige Gesamtmenge');for(const x of items){add(pid,loc,x.q*p.size,x.mhd,x.lot);record('in',pid,'Lieferung',loc,x.q*p.size,'MHD '+x.mhd+(x.lot?' · Charge '+x.lot:''))}await save();render();toast('Chargenlieferung gespeichert')}catch(err){toast('Lieferung nicht gespeichert: '+err.message)}}
function renderMhdControl(){
 const entries=state.units.filter(u=>u.mhd&&product(u.product)).sort((a,b)=>a.mhd.localeCompare(b.mhd));
 const buckets=new Map();
 for(const u of entries){const key=u.product+'|'+u.location+'|'+u.mhd+'|'+(u.lot||'');const b=buckets.get(key)||{u,qty:0};b.qty+=u.ml/product(u.product).size;buckets.set(key,b)}
 const alerts=[...buckets.values()].filter(b=>mhdDays(b.u.mhd)<=30);
 const unknown=state.units.filter(u=>!u.mhd).length;
 const rows=items=>items.map(({u,qty:q})=>{const p=product(u.product),days=mhdDays(u.mhd),label=days<0?'🔴 Abgelaufen seit '+(-days)+' Tagen':days<=30?'🟡 '+(days===0?'Heute fällig':'Noch '+days+' Tage'):'🟢 Noch '+days+' Tage';return '<div class="entry"><b>'+esc(p.name)+'</b><small>'+esc(u.location==='bar'?'Bar':'Hauptlager')+' · MHD '+esc(u.mhd)+(u.lot?' · Charge '+esc(u.lot):'')+' · '+esc(label)+' · '+fmt(q)+' Gebindeäquivalent(e)</small></div>'}).join('');
 return '<section class="card"><h2>MHD-Kontrolle</h2><p>Für Getränke und verderbliche Waren wird das Mindesthaltbarkeitsdatum je Gebinde gespeichert. Mehrere Chargen desselben Artikels dürfen unterschiedliche MHD haben. Das MHD ist kein automatisches Wegwerfdatum.</p><h3>Abgelaufen oder innerhalb von 30 Tagen</h3>'+(rows(alerts)||'<p>Keine erfassten MHD innerhalb der nächsten 30 Tage.</p>')+'<p><b>'+unknown+' Gebinde/Teilgebinde ohne erfasstes MHD.</b> Diese werden nicht als haltbar eingestuft.</p><h3>Alle erfassten MHD</h3>'+(rows([...buckets.values()])||'<p>Noch keine MHD hinterlegt.</p>')+'</section>'+
 renderMultiMhd()+'<section class="card"><h2>Wareneingang mit MHD</h2><form id="mhdReceive"><label>Artikel</label><select name="pid">'+optProducts()+'</select><label>Lagerort</label><select name="location"><option value="lager">Hauptlager</option><option value="bar">Bar</option></select><label>Anzahl ganzer Gebinde</label><input name="quantity" type="number" min="1" step="1" required value="1"><label>MHD laut Verpackung</label><input name="mhd" type="date" required><button>Wareneingang buchen</button></form></section>'+
 '<section class="card"><h2>MHD für vorhandenen Bestand nachtragen</h2><p>Nur ganze Gebinde ohne MHD werden zugeordnet. Der Bestand wird nicht erhöht.</p><form id="mhdAssign"><label>Artikel</label><select name="pid">'+optProducts()+'</select><label>Lagerort</label><select name="location"><option value="lager">Hauptlager</option><option value="bar">Bar</option></select><label>Anzahl ganzer Gebinde</label><input name="quantity" type="number" min="1" step="1" required value="1"><label>MHD</label><input name="mhd" type="date" required><button>MHD nachtragen</button></form></section>';
}
function mhdFormData(form){const f=new FormData(form),pid=String(f.get('pid')),loc=String(f.get('location')),q=Number(f.get('quantity')),mhd=String(f.get('mhd'));if(!product(pid)||!['lager','bar'].includes(loc)||!Number.isSafeInteger(q)||q<1||q>100000||!/^(?:19|20|21)\d{2}-\d{2}-\d{2}$/.test(mhd)||Number.isNaN(new Date(mhd+'T12:00:00Z').getTime())||new Date(mhd+'T12:00:00Z').toISOString().slice(0,10)!==mhd)throw Error('Artikel, Menge oder MHD ungültig');return {pid,loc,q,mhd}}
async function mhdReceive(e){e.preventDefault();try{const {pid,loc,q,mhd}=mhdFormData(e.target),ml=q*product(pid).size;if(!Number.isSafeInteger(ml))throw Error('Menge zu groß');add(pid,loc,ml,mhd);record('in',pid,'Lieferung',loc,ml,'MHD '+mhd);await save();render();toast('Wareneingang mit MHD gespeichert')}catch(err){toast(err.message)}}
async function mhdAssign(e){e.preventDefault();try{const {pid,loc,q,mhd}=mhdFormData(e.target),p=product(pid),units=state.units.filter(u=>u.product===pid&&u.location===loc&&!u.mhd&&u.ml===p.size);if(units.length<q)throw Error('Nicht genug ganze Gebinde ohne MHD vorhanden');for(const u of units.slice(0,q))u.mhd=mhd;await save();render();toast('MHD nachgetragen')}catch(err){toast(err.message)}}

function renderSyncStatus(){return '<section class="card"><h2>Supabase · Cloud-Anmeldung</h2><p class="warn"><b>Vorbereitung der Datenübernahme.</b> Die App speichert weiterhin lokal. Es erfolgt noch keine automatische Cloud-Übertragung.</p><p>Projekt: schlesisches-tor-lager</p><p>Lokale Artikel: '+state.products.length+' · Buchungen: '+state.movements.length+' · Veranstaltungen: '+state.events.length+'</p><form id="cloudLogin"><label>E-Mail-Adresse</label><input name="email" type="email" autocomplete="username" required><label>Passwort</label><input name="password" type="password" autocomplete="current-password" required><button>Cloud-Anmeldung prüfen</button></form><p id="cloudLoginStatus" aria-live="polite"></p><div id="cloudMigration" hidden><p>Einmalige sichere Übernahme. Vorhandene Cloud-Daten werden nicht überschrieben.</p><button type="button" id="cloudUpload">Lokale Daten einmalig in die Cloud übertragen</button><p id="cloudUploadStatus" aria-live="polite"></p></div><p>Nach erfolgreicher Anmeldung richten wir die sichere Übernahme der bisherigen Bestände ein. Die App wird erst nach erfolgreichem Test auf Cloud-Speicherung umgestellt.</p></section>'}
async function verifyCloudLogin(e){e.preventDefault();const form=e.currentTarget,f=new FormData(form),status=$('#cloudLoginStatus');status.textContent='Anmeldung wird geprüft …';try{const response=await fetch('https://bhwcvnwxuwdkcaehbdkw.supabase.co/auth/v1/token?grant_type=password',{method:'POST',headers:{'Content-Type':'application/json','apikey':'sb_publishable_SVm7NfdtMQTg_MPuqLraug_FCRIUpZN'},body:JSON.stringify({email:String(f.get('email')),password:String(f.get('password'))})});const data=await response.json();if(!response.ok||!data.access_token)throw Error(data.msg||data.error_description||data.message||'Anmeldung fehlgeschlagen');cloudAccessToken=data.access_token;cloudUserId=data.user?.id||null;status.textContent='Cloud-Anmeldung erfolgreich. Die lokalen Bestände wurden nicht verändert.';const migration=$('#cloudMigration');if(migration)migration.hidden=false;form.elements.namedItem('password').value='';}catch(err){status.textContent='Cloud-Anmeldung fehlgeschlagen: '+err.message}}

async function uploadInitialCloud(){const status=$('#cloudUploadStatus');if(!cloudAccessToken||!cloudUserId){status.textContent='Bitte erneut anmelden.';return}if(!confirm('Lokale Bestände, Artikel, Buchungen und Veranstaltungen erstmalig in Supabase kopieren? Vorhandene Cloud-Daten werden nicht überschrieben.'))return;const button=$('#cloudUpload');button.disabled=true;status.textContent='Cloud-Daten werden geprüft …';try{const base='https://bhwcvnwxuwdkcaehbdkw.supabase.co/rest/v1/lager_state',headers={'apikey':'sb_publishable_SVm7NfdtMQTg_MPuqLraug_FCRIUpZN','Authorization':'Bearer '+cloudAccessToken,'Content-Type':'application/json'};const check=await fetch(base+'?select=user_id,revision&user_id=eq.'+encodeURIComponent(cloudUserId),{headers});if(!check.ok)throw Error('Cloud-Abfrage: '+check.status+' '+(await check.text()).slice(0,180));const rows=await check.json();if(rows.length){status.textContent='In der Cloud liegen bereits Daten. Zur Sicherheit wurde nichts überschrieben.';return}const response=await fetch(base,{method:'POST',headers:{...headers,'Prefer':'return=representation'},body:JSON.stringify({user_id:cloudUserId,payload:structuredClone(state),revision:1})});if(!response.ok)throw Error('Übertragung: '+response.status+' '+(await response.text()).slice(0,180));const created=await response.json();if(created.length!==1)throw Error('Cloud-Bestätigung fehlt');status.textContent='Erstübertragung erfolgreich: '+state.products.length+' Artikel, '+state.movements.length+' Buchungen, '+state.events.length+' Veranstaltungen. Die App speichert vorerst weiterhin lokal.';}catch(err){status.textContent='Cloud-Übertragung fehlgeschlagen: '+err.message}finally{button.disabled=false}}

async function verifyCloudData(){const status=$('#cloudVerifyStatus');if(!cloudAccessToken||!cloudUserId){status.textContent='Bitte erneut anmelden.';return}status.textContent='Cloud-Daten werden geladen …';try{const url='https://bhwcvnwxuwdkcaehbdkw.supabase.co/rest/v1/lager_state?select=payload,revision&user_id=eq.'+encodeURIComponent(cloudUserId);const response=await fetch(url,{headers:{'apikey':'sb_publishable_SVm7NfdtMQTg_MPuqLraug_FCRIUpZN','Authorization':'Bearer '+cloudAccessToken}});if(!response.ok)throw Error('HTTP '+response.status+' '+(await response.text()).slice(0,150));const rows=await response.json();if(rows.length!==1)throw Error('Kein eindeutiger Cloud-Datensatz vorhanden');const remote=rows[0].payload;if(!remote||!Array.isArray(remote.products)||!Array.isArray(remote.units)||!Array.isArray(remote.movements)||!Array.isArray(remote.events))throw Error('Cloud-Daten unvollständig');const counts=[['Artikel',remote.products.length,state.products.length],['Bestände',remote.units.length,state.units.length],['Buchungen',remote.movements.length,state.movements.length],['Veranstaltungen',remote.events.length,state.events.length]];status.textContent='Cloud-Version '+rows[0].revision+' · '+counts.map(([name,cloud,local])=>name+': Cloud '+cloud+' / iPhone '+local).join(' · ')+(JSON.stringify(remote)===JSON.stringify(state)?' · Cloud und lokale Daten sind identisch.':' · Unterschiede vorhanden: keine Daten überschrieben.');}catch(err){status.textContent='Cloud-Prüfung fehlgeschlagen: '+err.message}}

async function scanBarcode(event){
 const scanSource=event?.currentTarget?.id||'';
 const box=$('#camera');
 if(!navigator.mediaDevices?.getUserMedia){box.innerHTML='<p class="warn">Kamera nicht verfügbar. Bitte die App über HTTPS in Safari öffnen.</p>';return}
 box.innerHTML='<p>Scanner wird geladen …</p>';
 try{
  if(!window.ZXingBrowser){
   await new Promise((resolve,reject)=>{
    const script=document.createElement('script');
    script.src='https://cdn.jsdelivr.net/npm/@zxing/browser@0.1.5/umd/zxing-browser.min.js';
    script.onload=resolve;script.onerror=()=>reject(new Error('Scannerbibliothek konnte nicht geladen werden'));
    document.head.appendChild(script);
   });
  }
  if(!window.ZXingBrowser?.BrowserMultiFormatReader)throw new Error('Scannerbibliothek nicht verfügbar');
  box.classList.add('scanner-fullscreen');document.body.classList.add('scanner-active');box.innerHTML='<div class="scanner-heading">Barcode scannen</div><video autoplay playsinline muted></video><div class="scanner-guide">Barcode vor die Kamera halten</div><button type="button" id="stopScan" class="secondary">Scanner schließen</button>';
  const video=box.querySelector('video');
  const reader=new ZXingBrowser.BrowserMultiFormatReader();
  const current={closed:false,controls:null,stream:null};scanner=current;
  $('#stopScan').onclick=()=>{stopScanner();box.innerHTML=''};
  current.controls=await reader.decodeFromConstraints({audio:false,video:{facingMode:{ideal:'environment'}}},video,(result,error,controls)=>{
   if(current.closed||!result)return;
   const value=result.getText();
   if(value){if(scanSource==='raspberryScan'&&$('#raspberryBarcode')){const field=$('#raspberryBarcode');field.value=value;stopScanner();box.innerHTML='';raspberryLookup();return}if(scanSource==='eventCountScan'&&$('#eventCountBarcode')){$('#eventCountBarcode').value=value;stopScanner();box.innerHTML='';eventCountSelect(value);return}if(scanSource==='eventScan'&&$('#eventBarcode')){const field=$('#eventBarcode');field.value=value;stopScanner();box.innerHTML='';selectEventBarcode();return}if(scanSource==='scanInventory'&&$('#inventoryBarcode')&&$('#inventoryContinuous')?.checked){const now=Date.now();if(current.lastCode===value&&now-current.lastAt<2200)return;current.lastCode=value;current.lastAt=now;captureInventoryScan(value);return}if(scanSource==='batchScan'&&$('#batchBarcode')&&$('#batchContinuous')?.checked){const now=Date.now();if(current.lastCode===value&&now-current.lastAt<2500)return;current.lastCode=value;current.lastAt=now;const p=state.products.find(x=>x.barcode===value);if(p){const existing=batchItems.find(x=>x.pid===p.id);if(existing)existing.quantity++;else batchItems.push({pid:p.id,quantity:1});renderBatch();updateFefoHints();$('#batchStatus').textContent='Erfasst: '+p.name+' · '+batchItems.reduce((n,x)=>n+x.quantity,0)+' Gebinde insgesamt';}else $('#batchStatus').textContent='EAN '+value+' nicht als Artikel gespeichert';return}const fieldBySource={scan:'#barcodeField',quickScan:'#quickBarcode',batchScan:'#batchBarcode',scanInventory:'#inventoryBarcode'};const field=$(fieldBySource[scanSource]||'#barcodeField');if(field)field.value=value;stopScanner();box.innerHTML='';toast('Barcode erkannt: '+value);if(scanSource==='batchScan')selectBatchBarcode();else if(scanSource==='quickScan')selectQuickBarcode();else if(scanSource==='scanInventory')selectInventoryBarcode();else if(scanSource==='scan')lookupBarcode()}
  });
  if(current.closed)current.controls?.stop();
 }catch(e){stopScanner();box.innerHTML='<p class="warn">Scanner konnte nicht gestartet werden. Prüfe Kameraberechtigung und Internetverbindung beim ersten Start. Barcode kann manuell eingegeben werden.</p>';console.error(e)}
}
function stopScanner(){if(scanner){scanner.closed=true;scanner.controls?.stop();scanner.stream?.getTracks().forEach(t=>t.stop());scanner=null}document.body.classList.remove('scanner-active');document.querySelector('#camera')?.classList.remove('scanner-fullscreen')}
(async()=>{try{state=await load();render();if('serviceWorker' in navigator&&location.protocol==='https:')navigator.serviceWorker.register('./sw.js').catch(()=>{});}catch(e){$('#app').innerHTML='<section class="card"><h2>Speicher nicht verfügbar</h2><p>Bitte Safari im normalen Modus verwenden. Fehler: '+esc(e.message)+'</p></section>'}})();
